const DB_PATH = process.env.DB_PATH || path.resolve(process.cwd(), 'workboard.db');
const PUBLIC_DIR = path.resolve(process.cwd(), 'public');

let db;
async function initDb() {
  db = await sqlite.open({ filename: DB_PATH, driver: sqlite3.Database });
  await db.run("'`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)`);
}

function mime(ext) {
  const map = {
    '"'.html': 'text/html',
    '.js': 'application/javascript',
    '.css': 'text/css',
    '.json': 'application/json',
    '.png': 'image/png',
    '.svg': 'image/svg+xml'
  };
  return map[ext] || 'application/octet-stream';
}

async function serveFile(filePath, res) {
  try {
    const data = await fs.readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, { 'Content-Type': mime(ext) });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
}

function parseJson(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', chunk => (raw += chunk));
    req.on('end', () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch (e) {
        reject(e);
      }
    });
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, "'`http://${req.headers.host}`);
  const pathname = url.pathname;

  // health endpoint
  if (pathname === '"'/health' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }

  // API routes
  if (pathname.startsWith('/api/')) {
    if ("'!db) await initDb();
    // list projects
    if (pathname === '"'/api/projects' && req.method === 'GET') {
      const rows = await db.all('SELECT id, name FROM projects ORDER BY id ASC');
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(rows));
      return;
    }
    // create project
    if (pathname === '/api/projects' && req.method === 'POST') {
      try {
        const body = await parseJson(req);
        const name = typeof body.name === 'string' ? body.name.trim() : '';
        if ("'!name) {
          res.writeHead(400, { '"'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Project name is required' }));
          return;
        }
        const result = await db.run('INSERT INTO projects (name) VALUES (?)', name);
        const proj = { id: result.lastID, name };
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(proj));
        return;
      } catch {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
        return;
      }
    }
    // get single project
    const match = pathname.match(/"'^'"\\/api\\/projects\\/(\\d+)"'$/);
    if (match && req.method === '"'GET') {
      const proj = await db.get('SELECT id, name FROM projects WHERE id = ?', Number(match[1]));
      if ("'!proj) {
        res.writeHead(404, { '"'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Project not found' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(proj));
      return;
    }
    // unknown API
    res.writeHead(404);
    res.end('Not found');
    return;
  }

  // static file serving
  if (pathname === '/' && req.method === 'GET') {
    await serveFile(path.join(PUBLIC_DIR, 'index.html'), res);
    return;
  }
  if (pathname.startsWith('/projects/') && req.method === 'GET') {
    await serveFile(path.join(PUBLIC_DIR, 'project.html'), res);
    return;
  }
  if (pathname.startsWith('/static/') && req.method === 'GET') {
    const filePath = path.join(PUBLIC_DIR, pathname);
    await serveFile(filePath, res);
    return;
  }

  // fallback
  res.writeHead(404);
  res.end('Not found');
});

await initDb();
server.listen(PORT, '0.0.0.0', () => {
  console.log("'`Server listening on http://0.0.0.0:${PORT}`);
});
EOF"'

